-- WarmRobot configuration-only export for native PostgreSQL 18.
-- Generated from Supabase project ocyzsyjohwyepmfvugrj.
-- Scope: ten configuration tables only. No Supabase Auth, Storage, RLS,
-- policies, users, wardrobe records, or recommendations are included.
-- The script is transactional and idempotent.
--
-- Source row counts:
--   materials: 17
--   categories: 31
--   thicknesses: 3
--   size_labels: 22
--   clothing_templates: 10
--   product_catalog: 18
--   category_product_links: 0
--   garment_variants: 321
--   category_style_guides: 44
--   category_guide_contents: 25
--
-- Compatibility exception: product_catalog.embedding is pgvector vector in
-- the source. This native PostgreSQL-only export uses text. All 18 source
-- values are NULL, so no vector value is omitted.

BEGIN;

CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE SCHEMA IF NOT EXISTS "warmrobot_config";
SET LOCAL search_path TO "warmrobot_config", public;

DO $enum$
BEGIN
  CREATE TYPE "warmrobot_config"."clothing_category" AS ENUM ('bodysuit', 'inner', 'mid', 'outer', 'pants', 'sleepwear', 'hat', 'socks', 'gloves', 'scarf', 'other', 'bodysuit_short', 'bodysuit_long', 'footed_romper', 'base_top', 'sweater', 'fleece_top', 'vest', 'pants_long', 'pants_short', 'pants_padded', 'outer_shell', 'outer_down', 'outer_cotton', 'outer_rain_uv', 'sleep_sack', 'pajamas', 'tshirt_short', 'tshirt_long', 'thermal_top', 'long_johns', 'pants_mid', 'outer_uv', 'shoes_sandal', 'shoes_sneaker', 'shoes_leather', 'shoes_boot');
EXCEPTION WHEN duplicate_object THEN NULL;
END
$enum$;

DO $enum$
BEGIN
  CREATE TYPE "warmrobot_config"."fabric_material" AS ENUM ('cotton_light', 'cotton_heavy', 'bamboo', 'fleece', 'wool_light', 'wool_heavy', 'down_light', 'down_heavy', 'waterproof', 'other', 'cotton', 'modal', 'acrylic', 'polyester', 'wool', 'down', 'unspecified');
EXCEPTION WHEN duplicate_object THEN NULL;
END
$enum$;

DO $enum$
BEGIN
  CREATE TYPE "warmrobot_config"."thickness_level" AS ENUM ('thin', 'medium', 'thick');
EXCEPTION WHEN duplicate_object THEN NULL;
END
$enum$;

CREATE TABLE IF NOT EXISTS "warmrobot_config"."materials" (
