      FOR EACH ROW EXECUTE FUNCTION "warmrobot_config"."set_updated_at"();
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid
    JOIN pg_namespace n ON n.oid = c.relnamespace
