    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'warmrobot_config' AND c.relname = 'product_catalog'
      AND t.tgname = 'product_catalog_updated_at' AND NOT t.tgisinternal
  ) THEN
    CREATE TRIGGER product_catalog_updated_at BEFORE UPDATE ON "warmrobot_config"."product_catalog"
      FOR EACH ROW EXECUTE FUNCTION "warmrobot_config"."set_updated_at"();
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'warmrobot_config' AND c.relname = 'category_product_links'
