    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'warmrobot_config' AND c.relname = 'garment_variants'
      AND t.tgname = 'garment_variants_updated_at' AND NOT t.tgisinternal
  ) THEN
    CREATE TRIGGER garment_variants_updated_at BEFORE UPDATE ON "warmrobot_config"."garment_variants"
      FOR EACH ROW EXECUTE FUNCTION "warmrobot_config"."set_updated_at"();
  END IF;
  IF NOT EXISTS (
