INSERT INTO "warmrobot_config"."category_style_guides"
SELECT * FROM jsonb_populate_recordset(NULL::"warmrobot_config"."category_style_guides", $category_style_guides_seed$[{"id":"e13f3cd9-2e42-4daa-a71a-e30b8a392a6b","cons":"腿部仍需另配外裤或袜子。","pros":"长袖保暖手臂，三角裆换尿布仍方便。","title":"三角款 · 纯棉","subtitle":"温天贴身","is_active":true,"created_at":"2026-08-26T15:24:06.312924+00:00","sort_order":10,"updated_at":"2026-08-26T15:24:06.312924+00:00","usage_tips":"春秋室内、需长袖但不想穿秋衣时。","category_id":"f2f55879-2868-48e5-96ac-93e1fc03d813","category_code":"bodysuit_long"},{"id":"4b6c0724-c9f9-4c8c-bb6f-6944c00c3079","cons":"换尿布较慢；过热时不好分层脱。","pros":"躯干与腿同层保暖，减少空隙灌风。","title":"长裤款 · 中厚棉","subtitle":"一体更暖","is_active":true,"created_at":"2026-08-26T15:24:06.312924+00:00","sort_order":20,"updated_at":"2026-08-26T15:24:06.312924+00:00","usage_tips":"凉天居家、睡眠或短途抱娃出门。","category_id":"f2f55879-2868-48e5-96ac-93e1fc03d813","category_code":"bodysuit_long"},{"id":"c1035b06-53fa-4bbf-97e5-d32991a887e2","cons":"单穿在大风天不够挡风。","pros":"薄长袖不显臃肿，叠穿空间大。","title":"莫代尔/混纺薄长袖","subtitle":"过渡季贴身","is_active":true,"created_at":"2026-08-26T15:24:06.312924+00:00","sort_order":30,"updated_at":"2026-08-26T15:24:06.312924+00:00","usage_tips":"温凉交界、白天室内偏暖时。","category_id":"f2f55879-2868-48e5-96ac-93e1fc03d813","category_code":"bodysuit_long"},{"id":"c0899d23-ef46-4ecb-9619-78b5636181da","cons":"腿部覆盖少，偏凉时略显单薄。","pros":"裆部按扣多，换尿布不必脱衣；纯棉亲肤透气。","title":"三角款 · 纯棉","subtitle":"换尿布最快","is_active":true,"created_at":"2026-08-26T15:24:06.312924+00:00","sort_order":10,"updated_at":"2026-08-26T15:24:06.312924+00:00","usage_tips":"热天居家、频繁换尿布的小月龄首选。","category_id":"716fe676-8101-4214-b260-3e850add0a32","category_code":"bodysuit_short"},{"id":"6882f1a9-97ea-426f-baa5-fffe546ae30e","cons":"换尿布稍慢于三角款。","pros":"比三角多盖一点腿，活动时不易走光。","title":"平裤款 · 纯棉","subtitle":"更遮大腿","is_active":true,"created_at":"2026-08-26T15:24:06.312924+00:00","sort_order":20,"updated_at":"2026-08-26T15:24:06.312924+00:00","usage_tips":"暖天出门短途、希望稍多覆盖时。","category_id":"716fe676-8101-4214-b260-3e850add0a32","category_code":"bodysuit_short"},{"id":"c8ea0366-1467-430c-bf20-8790e581153b","cons":"热天可能偏闷，换尿布步骤更多。","pros":"连脚/长裤一体，省去另穿短裤。","title":"长裤款 · 纯棉","subtitle":"一条顶上下","is_active":true,"created_at":"2026-08-26T15:24:06.312924+00:00","sort_order":30,"updated_at":"2026-08-26T15:24:06.312924+00:00","usage_tips":"微凉过渡天、想减少单品件数时。","category_id":"716fe676-8101-4214-b260-3e850add0a32","category_code":"bodysuit_short"},{"id":"ca8e455f-7803-4afa-8bfc-df93ef9ec645","cons":"耐磨与定型略逊于纯棉；价位通常更高。","pros":"手感滑软、吸湿快干，闷热天更舒服。","title":"莫代尔薄款","subtitle":"凉感柔软","is_active":true,"created_at":"2026-08-26T15:24:06.312924+00:00","sort_order":40,"updated_at":"2026-08-26T15:24:06.312924+00:00","usage_tips":"湿热天气、出汗多或爱踢被的宝宝。","category_id":"716fe676-8101-4214-b260-3e850add0a32","category_code":"bodysuit_short"},{"id":"5451d005-7fa3-4197-b553-d55729c93826","cons":"贴身透气与亲肤感一般不如棉/莫代尔。","pros":"洗后干得快，颜色更耐洗。","title":"腈纶/涤纶混纺","subtitle":"易干耐穿","is_active":true,"created_at":"2026-08-26T15:24:06.312924+00:00","sort_order":50,"updated_at":"2026-08-26T15:24:06.312924+00:00","usage_tips":"备洗量大、常外出洗衣不便时当备份。","category_id":"716fe676-8101-4214-b260-3e850add0a32","category_code":"bodysuit_short"},{"id":"b4cdb554-ae1c-41af-97df-149f994241e5","cons":"静电与起球；闷热时偏捂。","pros":"比针织更耐磨，适合爬行玩耍。","title":"薄卫衣/抓绒","subtitle":"抗凉又好动","is_active":true,"created_at":"2026-08-26T15:24:06.312924+00:00","sort_order":10,"updated_at":"2026-08-26T15:24:06.312924+00:00","usage_tips":"凉天户外活动、幼儿园接送。","category_id":"938bc07f-a64f-4e64-8913-bc437d33fb6d","category_code":"fleece_top"},{"id":"89d3d968-e113-4594-a2b6-0e0790a41963","cons":"室内暖气房容易过热。","pros":"挡凉风好于薄卫衣。","title":"中厚抓绒","subtitle":"风大时更暖","is_active":true,"created_at":"2026-08-26T15:24:06.312924+00:00","sort_order":20,"updated_at":"2026-08-26T15:24:06.312924+00:00","usage_tips":"冷天短途出门、公园玩耍。","category_id":"938bc07f-a64f-4e64-8913-bc437d33fb6d","category_code":"fleece_top"},{"id":"66d19130-c68d-4b46-ba88-a8c8d17c88d8","cons":"小月龄易扯掉；影响抓握。","pros":"手背少受风。","title":"薄手套","subtitle":"护手防凉","is_a